// UI host tests — run: node tests/test_ui_host.js  (exit 0 = pass)
// Includes the cross-language hash-vector reproduction (tests/hash_vectors.json,
// generated by the Python helper) — that reproduction IS the cross-language check.
const assert = require("assert");
const http = require("http");
const fs = require("fs");
const path = require("path");
const { UiHost, startServer, callHash, normalize } = require("../ui-host/ui_host.js");

let failures = 0, passed = 0;
function ok(name) { passed++; console.log("ok -", name); }
function bad(name, e) { failures++; console.error("FAIL -", name, "\n ", e.message); }

(async () => {
  const ui = new UiHost();

  // ---- guard logic ----
  try { ui.approve("powershell", { cmd: "x" }, null); bad("deny at mint", new Error("allowed")); }
  catch (e) { ok("deny at mint: powershell refused"); }
  try { ui.approve("mcp__gmail__send", {}, null); bad("mcp deny", new Error("allowed")); }
  catch (e) { ok("deny at mint: mcp__ prefixed refused"); }
  try { ui.approve("omg.tool", {}, null); bad("unknown", new Error("allowed")); }
  catch (e) { ok("deny at mint: unknown tool refused"); }

  try {
    ui.approve("ui.click", { pid: 5, window: "w", control: "c" }, null);
    bad("target required", new Error("allowed"));
  } catch (e) { ok("ui.* approval without target refused"); }

  try {
    const h = ui.approve("ui.click", { pid: 5, window: "w", control: "c" }, { pid: 5, window: "w", control: "c" });
    assert.ok(/^[0-9a-f]{64}$/.test(h) && ui.has(h));
    ok("ui.* approval yields 64-hex hash");
  } catch (e) { bad("hash mint", e); }

  // key order + canonical
  try {
    const h1 = ui.approve("ui.type", { b: 2, a: 1, pid: 1, window: "w", control: "c" }, { pid: 1, window: "w", control: "c" });
    const h2 = callHash("ui.type", { a: 1, b: 2, pid: 1, window: "w", control: "c" });
    assert.strictEqual(h1, h2);
    ok("hash stable across key order");
  } catch (e) { bad("key order", e); }

  // float normalization
  try { assert.deepStrictEqual(normalize({ x: 1.0, y: [2.0, 3.5], z: { n: 7.0 } }), { x: 1, y: [2, 3.5], z: { n: 7 } }); ok("normalize: 1.0->1 (nested, non-integer kept)"); }
  catch (e) { bad("normalize floats", e); }

  // __ stripping
  try { assert.strictEqual(callHash("ui.click", { a: 1, __secret: 2 }), callHash("ui.click", { a: 1 })); ok("__-keys stripped from hash"); }
  catch (e) { bad("__ strip", e); }

  // irreversible at mint + confirm_second
  try {
    const h = ui.approve("ui.click", { pid: 1, window: "w", control: "Delete" }, { pid: 1, window: "w", control: "Delete" }, "delete-file");
    const ap = ui.approvals.get(h);
    assert.ok(ap.requiresSecond && !ap.secondConfirmed);
    ok("irreversible action class requires second confirm");
    let threw = false;
    try { ui.confirmSecond(h, { pid: 1, window: "w", control: "Other" }); } catch (e) { threw = true; }
    assert.ok(threw);
    ok("confirm-second wrong target refused");
    ui.confirmSecond(h, { pid: 1, window: "w", control: "Delete" });
    assert.ok(ui.approvals.get(h).secondConfirmed);
    ok("confirm-second with exact target passes");
  } catch (e) { bad("confirm-second flow", e); }

  // ---- cross-language vectors: Node must reproduce Python-generated hashes ----
  try {
    const vectors = JSON.parse(fs.readFileSync(path.join(__dirname, "hash_vectors.json"), "utf8"));
    for (const v of vectors) {
      assert.strictEqual(callHash(v.name, v.args), v.sha256,
        `vector ${v.name} ${JSON.stringify(v.args)}`);
    }
    ok(`cross-language: all ${vectors.length} Python-generated hash vectors reproduced`);
  } catch (e) { bad("cross-language vectors", e); }

  // ---- network hardening ----
  const u2 = new UiHost();
  const PORT = 7441;
  const server = startServer(u2, PORT);
  await new Promise((r) => setTimeout(r, 150));

  const probe = (headers, body) => new Promise((resolve) => {
    const req = http.request({ host: "127.0.0.1", port: PORT, path: "/status", method: "POST", headers }, (res) => {
      res.resume(); res.on("end", () => resolve(res.statusCode));
    });
    req.end(body || JSON.stringify({ token: u2.launchToken }));
  });

  const goodBody = JSON.stringify({ token: u2.launchToken });
  const cases = [
    ["bad Host 127.0.0.1:1 rejected", { Host: "127.0.0.1:1", "content-type": "application/json" }, goodBody, 403],
    ["bad Host 127.0.0.1:7441.evil rejected", { Host: "127.0.0.1:7441.evil", "content-type": "application/json" }, goodBody, 403],
    ["good Host localhost:7441 accepted", { Host: "localhost:7441", "content-type": "application/json" }, goodBody, 200],
    ["good Host 127.0.0.1:7441 accepted", { Host: "127.0.0.1:7441", "content-type": "application/json" }, goodBody, 200],
    ["wrong port in Host rejected", { Host: "127.0.0.1:9999", "content-type": "application/json" }, goodBody, 403],
    ["bad token 401", { Host: "localhost:7441", "content-type": "application/json" }, JSON.stringify({ token: "nope" }), 401],
    ["cross-origin 403", { Host: "localhost:7441", Origin: "https://x.example", "content-type": "application/json" }, goodBody, 403],
  ];
  for (const [name, headers, body, want] of cases) {
    const got = await probe(headers, body);
    if (got === want) ok(name); else bad(name, new Error(`expected ${want}, got ${got}`));
  }

  // /confirm-second over HTTP
  try {
    const h = u2.approve("ui.click", { pid: 9, window: "w", control: "Del" }, { pid: 9, window: "w", control: "Del" }, "recycle");
    const r2 = await new Promise((resolve) => {
      const req = http.request({ host: "127.0.0.1", port: PORT, path: "/confirm-second", method: "POST", headers: { Host: `localhost:${PORT}`, "content-type": "application/json" } }, (res) => {
        let b = ""; res.on("data", (c) => (b += c)); res.on("end", () => resolve({ s: res.statusCode, b }));
      });
      req.end(JSON.stringify({ token: u2.launchToken, hash: h, target: { pid: 9, window: "w", control: "Del" } }));
    });
    assert.strictEqual(r2.s, 200);
    ok("/confirm-second endpoint works with exact target");
  } catch (e) { bad("confirm-second http", e); }

  server.close();
  console.log(`\n${passed} passed, ${failures} failed`);
  process.exit(failures ? 1 : 0);
})();
